    function objectBox(o){ if(o.type==='biological-cell-boundary'||o.type==='biological-organelle'||o.type==='biological-label') return {x:o.x,y:o.y,w:o.width,h:o.height}; if(o.type==='biological-arrow') return {x:Math.min(o.x1,o.x2),y:Math.min(o.y1,o.y2),w:Math.abs(o.x2-o.x1),h:Math.abs(o.y2-o.y1)}; if(o.type==='text') return {x:o.x,y:o.y-o.fontSize,w:Math.max(100,String(o.text||'').length*o.fontSize*.55),h:o.fontSize+10}; return null; }
    function portPoint(o,port){ const b=objectBox(o)||{x:0,y:0,w:0,h:0}; const map={n:[.5,0],ne:[1,0],e:[1,.5],se:[1,1],s:[.5,1],sw:[0,1],w:[0,.5],nw:[0,0]};const [px,py]=map[port]||map.e;return{x:b.x+b.w*px,y:b.y+b.h*py}; }
    function pointerPoint(event){ const rect=state.svg.getBoundingClientRect(),vb=state.svg.viewBox.baseVal;return{x:(event.clientX-rect.left)*vb.width/rect.width+vb.x,y:(event.clientY-rect.top)*vb.height/rect.height+vb.y}; }
    function closestPort(o,p){ let best='e',dist=Infinity;PORTS.forEach((port)=>{const q=portPoint(o,port),d=(q.x-p.x)**2+(q.y-p.y)**2;if(d<dist){dist=d;best=port;}});return best; }
    function findObjectFromTarget(target){ const hit=target.closest?.('[data-bio-hit-object]');if(hit)return objectById(hit.getAttribute('data-bio-hit-object'));const node=target.closest?.('[data-qmx-object]');return node?objectById(node.getAttribute('data-qmx-object')):null; }
    function createToolObject(tool,p){ if(['animal-cell','plant-cell','bacterium'].includes(tool)){const kind=tool==='animal-cell'?'animal':tool==='plant-cell'?'plant':'bacterium';return makeBoundary(kind,{x:snap(p.x-180),y:snap(p.y-120),width:360,height:240});} if(['nucleus','mitochondrion','chloroplast','vacuole','golgi','rough-er','smooth-er','ribosome','lysosome','centriole','plasmid','flagellum'].includes(tool))return makeOrganelle(tool,{x:snap(p.x-60),y:snap(p.y-40)}); if(tool==='process-arrow')return makeArrow({x1:snap(p.x-120),y1:snap(p.y),x2:snap(p.x+120),y2:snap(p.y)}); if(tool==='text')return makeText({x:snap(p.x),y:snap(p.y)}); return null; }
    function selectionMarkup(){
        const parts=[];
        if(state.activeTool==='select')state.document.objects.forEach((object)=>{
            const id=esc(object.id),box=objectBox(object);
            if(object.type==='biological-arrow')parts.push(`<line class="qmx-bio-hit" data-bio-hit-object="${id}" x1="${object.x1}" y1="${object.y1}" x2="${object.x2}" y2="${object.y2}" stroke="transparent" stroke-width="22" pointer-events="stroke"/>`);
            else if(box)parts.push(`<rect class="qmx-bio-hit" data-bio-hit-object="${id}" x="${box.x}" y="${box.y}" width="${Math.max(12,box.w)}" height="${Math.max(12,box.h)}" fill="transparent" stroke="none" pointer-events="all"/>`);
        });
        if(state.activeTool==='smart-label')targetObjects().forEach((o)=>PORTS.forEach((port)=>{const p=portPoint(o,port),active=state.labelStart?.objectId===o.id&&state.labelStart?.port===port;parts.push(`<circle data-bio-target="${esc(o.id)}" data-bio-port="${port}" cx="${p.x}" cy="${p.y}" r="7.5" fill="${active?'#f59e0b':'#22c55e'}" stroke="#fff" stroke-width="2" style="cursor:crosshair"/>`);}));
        const o=selectedObject(),b=o&&objectBox(o);if(b)parts.push(`<rect x="${b.x-7}" y="${b.y-7}" width="${Math.max(14,b.w+14)}" height="${Math.max(14,b.h+14)}" fill="none" stroke="#2563eb" stroke-width="2" stroke-dasharray="7 5" pointer-events="none"/>`);return parts.join('');
    }
    function render(){ if(!state.canvas||!state.document)return;state.document=Diagram.normalizeSpec(state.document);let svg=Diagram.svgMarkup(state.document);svg=svg.replace('</svg>',`${selectionMarkup()}</svg>`);state.canvas.innerHTML=svg;state.svg=state.canvas.querySelector('svg');syncSelectedControls();updateSummary(); }
    function pushHistory(){ const value=JSON.stringify(state.document);if(state.history[state.historyIndex]===value)return;state.history=state.history.slice(0,state.historyIndex+1);state.history.push(value);if(state.history.length>80)state.history.shift();state.historyIndex=state.history.length-1;updateHistoryButtons(); }
    function restoreHistory(index){ if(index<0||index>=state.history.length)return;state.historyIndex=index;state.document=Diagram.normalizeSpec(JSON.parse(state.history[index]));state.selectedId=null;state.labelStart=null;state.interaction=null;syncDocumentControls();render();updateHistoryButtons(); }
    function undo(){restoreHistory(state.historyIndex-1);} function redo(){restoreHistory(state.historyIndex+1);} function updateHistoryButtons(){if(state.controls.undo)state.controls.undo.disabled=state.historyIndex<=0;if(state.controls.redo)state.controls.redo.disabled=state.historyIndex>=state.history.length-1;}
    function setStatus(message){if(state.controls.status)state.controls.status.textContent=message||'';}
    function setTool(tool,announce=true){state.activeTool=tool;state.labelStart=null;state.controls.tools?.querySelectorAll('[data-tool]').forEach((b)=>b.classList.toggle('active',b.dataset.tool===tool));if(announce)setStatus(tool==='smart-label'?'Click an organelle/cell connection point, then click the label position.':`${tool} selected.`);render();}
    function updateSummary(){if(!state.controls.summary)return;const counts={cells:0,organelles:0,labels:0,arrows:0};state.document.objects.forEach((o)=>{if(o.type==='biological-cell-boundary')counts.cells++;else if(o.type==='biological-organelle')counts.organelles++;else if(o.type==='biological-label')counts.labels++;else if(o.type==='biological-arrow')counts.arrows++;});state.controls.summary.innerHTML=`<strong>Objects</strong><br>Cells: ${counts.cells}<br>Organelles: ${counts.organelles}<br>Labels: ${counts.labels}<br>Arrows: ${counts.arrows}<br>Total: ${state.document.objects.length}`;}
    function field(label,key,value,type='text',extra=''){return`<div class="qmx-bio-field"><label>${esc(label)}</label><input type="${type}" data-prop="${key}" value="${esc(value)}" ${extra}></div>`;}
    function selectField(label,key,value,options){return`<div class="qmx-bio-field"><label>${esc(label)}</label><select data-prop="${key}">${options.map(([v,l])=>`<option value="${esc(v)}"${String(v)===String(value)?' selected':''}>${esc(l)}</option>`).join('')}</select></div>`;}
    function syncSelectedControls(){const host=state.controls.selected;if(!host)return;const o=selectedObject();if(!o){host.innerHTML='<p class="qmx-bio-muted">Select an object to edit its properties.</p>';return;}let html=`<div class="qmx-bio-object-type">${esc(o.type)}</div>`;if(o.type==='biological-cell-boundary')html+=selectField('Cell type','kind',o.kind,[['animal','Animal'],['plant','Plant'],['bacterium','Bacterium']])+field('Label','label',o.label)+`<div class="qmx-bio-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Width','width',o.width,'number')}${field('Height','height',o.height,'number')}${field('Fill','fill',o.fill,'color')}${field('Stroke','stroke',o.stroke,'color')}</div>`;else if(o.type==='biological-organelle')html+=selectField('Organelle','kind',o.kind,[['nucleus','Nucleus'],['mitochondrion','Mitochondrion'],['chloroplast','Chloroplast'],['vacuole','Vacuole'],['golgi','Golgi'],['rough-er','Rough ER'],['smooth-er','Smooth ER'],['ribosome','Ribosome'],['lysosome','Lysosome'],['centriole','Centriole'],['plasmid','Plasmid'],['flagellum','Flagellum']])+field('Label','label',o.label)+`<div class="qmx-bio-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Width','width',o.width,'number')}${field('Height','height',o.height,'number')}${field('Rotation','rotation',o.rotation,'number')}${field('Details','detailCount',o.detailCount,'number','min="1" max="20"')}${field('Fill','fill',o.fill,'color')}${field('Stroke','stroke',o.stroke,'color')}</div>`;else if(o.type==='biological-label')html+=field('Label text','text',o.text)+selectField('Target port','targetPort',o.targetPort,PORTS.map((p)=>[p,p.toUpperCase()]))+`<div class="qmx-bio-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Width','width',o.width,'number')}${field('Height','height',o.height,'number')}${field('Fill','fill',o.fill,'color')}${field('Stroke','stroke',o.stroke,'color')}</div>`;else if(o.type==='biological-arrow')html+=field('Arrow label','label',o.label)+`<label class="qmx-bio-check"><input type="checkbox" data-prop="dashed"${o.dashed?' checked':''}> Dashed line</label><div class="qmx-bio-grid2">${field('X1','x1',o.x1,'number')}${field('Y1','y1',o.y1,'number')}${field('X2','x2',o.x2,'number')}${field('Y2','y2',o.y2,'number')}${field('Stroke','stroke',o.stroke,'color')}${field('Line width','lineWidth',o.lineWidth,'number','step="0.1"')}</div>`;else if(o.type==='text')html+=`<div class="qmx-bio-field"><label>Text</label><textarea data-prop="text">${esc(o.text)}</textarea></div><div class="qmx-bio-grid2">${field('X','x',o.x,'number')}${field('Y','y',o.y,'number')}${field('Font size','fontSize',o.fontSize,'number')}${field('Color','color',o.color,'color')}</div>`;host.innerHTML=html;}
    function syncDocumentControls(){if(!state.root||!state.document)return;state.root.querySelectorAll('[data-doc]').forEach((input)=>{const key=input.dataset.doc;if(input.type==='checkbox')input.checked=Boolean(state.document[key]);else input.value=state.document[key]??'';});}
